const queries=[
  ["created1","repo:entireio/cli is:pr created:>=2026-08-10",1],
  ["created2","repo:entireio/cli is:pr created:>=2026-08-10",2],
  ["created3","repo:entireio/cli is:pr created:>=2026-08-10",3],
  ["older_closed","repo:entireio/cli is:pr closed:>=2026-08-10 created:<2026-08-10",1]
];
const rs=await Promise.all(queries.map(([name,q,page])=>tools.exec_command({
  cmd:`gh api -X GET search/issues -f q='${q}' -f sort=created -f order=desc -f per_page=100 -f page=${page} --jq '.items[] | [.number,.state,(.pull_request.merged_at // "-"),.created_at,(.closed_at // "-"),.title,.html_url] | @tsv'`,
  workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/entire-bug-fixes",
  yield_time_ms:30000,max_output_tokens:15000,
  sandbox_permissions:"require_escalated",
  justification:"May I retrieve the compact metadata needed to classify the complete recent PR set?",
  prefix_rule:["gh","api","-X","GET","search/issues"]
})));
const byNum=new Map();
for(const r of rs){
  for(const line of r.output.trim().split("\n")){
    if(!line) continue;
    const [number,state,mergedAt,createdAt,closedAt,title,url]=line.split("\t");
    byNum.set(Number(number),{number:Number(number),state,mergedAt,createdAt,closedAt,title,url});
  }
}
const prs=[...byNum.values()];
store("recent_pr_index",prs);
const kinds={fix:0,feature:0,performance:0,test_ci:0,refactor_cleanup:0,docs_release_deps:0,other:0};
const areas={
  "checkpoint/session lifecycle":0,
  "agent integrations & hooks":0,
  "cloud, auth & routing":0,
  "search/review/dispatch UX":0,
  "security, privacy & filesystem safety":0,
  "tests, CI, install & developer tooling":0,
  "performance & scalability":0,
  "settings/configuration":0
};
for(const pr of prs){
  const t=pr.title.toLowerCase();
  if(/^fix(\(|:|\b)/.test(t)) kinds.fix++;
  else if(/^feat(\(|:|\b)/.test(t)||/^add\b/.test(t)||/^introduce\b/.test(t)) kinds.feature++;
  else if(/^perf(\(|:|\b)/.test(t)) kinds.performance++;
  else if(/^test(\(|:|\b)/.test(t)||/\be2e\b|\bci\b/.test(t)) kinds.test_ci++;
  else if(/^refactor(\(|:|\b)/.test(t)||/\bremove\b|\bcleanup\b|\bstale\b|\bdead\b/.test(t)) kinds.refactor_cleanup++;
  else if(/^docs?(\(|:|\b)/.test(t)||/^chore(\(|:|\b)/.test(t)||/\bchangelog\b|\bdependabot\b|\bdeps\b/.test(t)) kinds.docs_release_deps++;
  else kinds.other++;
  if(/checkpoint|session|transcript|shadow|condens|trail|attach|resume|adopt|import|strategy|rewind|sweep|opf/.test(t)) areas["checkpoint/session lifecycle"]++;
  if(/agent|hook|claude|codex|cursor|gemini|opencode|grok|goose|qwen|pi\b|vogon|factory|copilot|external/.test(t)) areas["agent integrations & hooks"]++;
  if(/auth|login|logout|jurisdiction|cell|cluster|core|api|mirror|grant|organization|project|control.plane/.test(t)) areas["cloud, auth & routing"]++;
  if(/search|review|dispatch|investigat|blame|why|expert|token report|tokens/.test(t)) areas["search/review/dispatch UX"]++;
  if(/redact|secret|privacy|symlink|filesystem|permission|trust|credential|forg|unsafe|security/.test(t)) areas["security, privacy & filesystem safety"]++;
  if(/test|e2e|ci\b|lint|deps|build|install|windows|flake|logging|telemetry|doctor|mise|release/.test(t)) areas["tests, CI, install & developer tooling"]++;
  if(/^perf|performance|faster|batch|cache|parallel|latency|o\\(n/.test(t)) areas["performance & scalability"]++;
  if(/setting|configur|enable|disable|status/.test(t)) areas["settings/configuration"]++;
}
const states={open:0,merged:0,closed_unmerged:0};
for(const p of prs){ if(p.mergedAt!=="-")states.merged++; else if(p.state==="open")states.open++; else states.closed_unmerged++; }
text(JSON.stringify({unique:prs.length,states,kinds,areas},null,2));

