    14	)
    15	
    16	// Compile-time interface assertion.
    17	var _ agent.TranscriptAnalyzer = (*CursorAgent)(nil)
    18	
    19	// GetTranscriptPosition returns the current line count of a Cursor transcript.
    20	// Cursor uses the same JSONL format as Claude Code, so position is the number of lines.
    21	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
    22	// Returns 0 if the file doesn't exist or is empty.
    23	func (c *CursorAgent) GetTranscriptPosition(path string) (int, error) {
    24		if path == "" {
    25			return 0, nil
    26		}
    27	
    28		file, err := os.Open(path) //nolint:gosec // Path comes from Cursor transcript location
    29		if err != nil {
    30			if os.IsNotExist(err) {
    31				return 0, nil
    32			}
    33			return 0, fmt.Errorf("failed to open transcript file: %w", err)
    34		}
    35		defer file.Close()
    36	
    37		reader := bufio.NewReader(file)
    38		lineCount := 0
    39	
    40		for {
    41			line, err := reader.ReadBytes('\n')
    42			if err != nil {
    43				if err == io.EOF {
    44					if len(line) > 0 {
    45						lineCount++ // Count final line without trailing newline
    46					}
    47					break
    48				}
    49				return 0, fmt.Errorf("failed to read transcript: %w", err)
    50			}
    51			lineCount++
    52		}
    53	
    54		return lineCount, nil
    55	}
    56	
    57	// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
    58	// Cursor uses the same JSONL format as Claude Code; the shared transcript package normalizes
    59	// "role" → "type" and strips <user_query> tags.
    60	func (c *CursorAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
    61		lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
    62		if err != nil {
    63			return nil, fmt.Errorf("failed to parse transcript: %w", err)
    64		}
    65	
    66		var prompts []string
    67		for i := range lines {
    68			if lines[i].Type != transcript.TypeUser {
    69				continue
    70			}
    71			// ExtractUserContent already strips IDE tags; stripping again is not a
    72			// no-op now that the <timestamp> strip is position-anchored.
    73			content := transcript.ExtractUserContent(lines[i].Message)
    74			if content != "" {
    75				prompts = append(prompts, content)
    76			}
    77		}
    78		return prompts, nil
    79	}
    80	
    81	// ExtractSummary extracts the last assistant message as a session summary.
    82	func (c *CursorAgent) ExtractSummary(sessionRef string) (string, error) {
    83		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
    84		if err != nil {
    85			return "", fmt.Errorf("failed to read transcript: %w", err)
    86		}
    87	
    88		lines, parseErr := transcript.ParseFromBytes(data)
    89		if parseErr != nil {
    90			return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
    91		}
    92	
    93		// Walk backward to find last assistant text block
    94		for i := len(lines) - 1; i >= 0; i-- {
    95			if lines[i].Type != transcript.TypeAssistant {
    96				continue
    97			}
    98			var msg transcript.AssistantMessage
    99			if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
   100				continue
   101			}
   102			for _, block := range msg.Content {
   103				if block.Type == transcript.ContentTypeText && block.Text != "" {
   104					return block.Text, nil
   105				}
   106			}
   107		}
   108		return "", nil
   109	}
   110	
   111	// ExtractModifiedFiles extracts the files modified by Cursor tool calls in the
   112	// given transcript lines, in first-seen order and deduplicated.
   113	//
   114	// Cursor records tool_use content blocks in the same shape as Claude Code
   115	// (message.content[i].type == "tool_use", with name and input), so this mirrors
   116	// claudecode.ExtractModifiedFiles. The divergences are the tool names and the
   117	// input key — see FileModificationTools and toolInput.
   118	func ExtractModifiedFiles(lines []transcript.Line) []string {
   119		seen := make(map[string]bool)
   120		var files []string
   121	
   122		for i := range lines {
   123			if lines[i].Type != transcript.TypeAssistant {
   124				continue
   125			}
   126			var msg transcript.AssistantMessage
   127			if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
   128				continue
   129			}
   130			for _, block := range msg.Content {
   131				if block.Type != transcript.ContentTypeToolUse {
   132					continue
   133				}
   134				if !slices.Contains(FileModificationTools, block.Name) {
   135					continue
   136				}
   137				var input toolInput
   138				if err := json.Unmarshal(block.Input, &input); err != nil {
   139					continue
   140				}
   141				if input.Path == "" || seen[input.Path] {
   142					continue
   143				}
   144				seen[input.Path] = true
   145				files = append(files, input.Path)
   146			}
   147		}
   148		return files
   149	}
   150	
   151	// ExtractModifiedFilesFromOffset extracts files modified by tool calls appearing at
   152	// or after startOffset, and returns the transcript's current line count.
   153	//
   154	// A missing transcript is not an error: Cursor reports transcript_path as null in
   155	// CLI mode, so ResolveSessionFile predicts a path that may not exist yet, and this
   156	// runs on capture paths that must fail open (matching GetTranscriptPosition).
   157	func (c *CursorAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
   158		if path == "" {
   159			return nil, 0, nil
   160		}
   161	
   162		lines, total, err := transcript.ParseFromFileAtLineWithTotal(path, startOffset)
   163		if err != nil {
   164			if errors.Is(err, os.ErrNotExist) {
   165				return nil, 0, nil
   166			}
   167			return nil, 0, fmt.Errorf("failed to parse transcript: %w", err)
   168		}
   169	
   170		return ExtractModifiedFiles(lines), total, nil
   171	}

