  1	package claudecode
  2	
  3	import (
  4		"bytes"
  5		"encoding/json"
  6	
  7		"github.com/entireio/cli/cmd/entire/cli/agent"
  8		"github.com/entireio/cli/cmd/entire/cli/transcript"
  9	)
 10	
 11	// toolUseToken is the literal that must appear in a raw transcript line for it
 12	// to carry a tool_use content block. Both quotes are part of the token on
 13	// purpose: it makes the check exact without whitespace normalization, and it is
 14	// what keeps `"tool_use_id"` — which appears on every tool_result line, the
 15	// single largest false-positive class for any substring probe — from matching.
 16	var toolUseToken = []byte(`"tool_use"`)
 17	
 18	// ScanToolInvocations walks the Bash/Task-style tool calls recorded in a Claude
 19	// Code JSONL transcript. See agent.ToolInvocationScanner for the contract,
 20	// including that hints is a performance filter and not a semantic one.
 21	//
 22	// Lines are split by hand with bytes.IndexByte rather than with bufio.Scanner:
 23	// a single Claude Code transcript line routinely carries a multi-megabyte tool
 24	// result, so Scanner's 64KiB default token limit would silently truncate the
 25	// walk. Two byte-level prefilters run before any JSON work, so a transcript
 26	// with no candidate line costs one pass and zero allocations — the same order
 27	// as the substring probe this replaces, on the miss path that dominates.
 28	func (c *ClaudeCodeAgent) ScanToolInvocations(transcriptData []byte, hints [][]byte, visit func(agent.ToolInvocation) bool) bool {
 29		for rest := transcriptData; len(rest) > 0; {
 30			line := rest
 31			if idx := bytes.IndexByte(rest, '\n'); idx >= 0 {
 32				line, rest = rest[:idx], rest[idx+1:]
 33			} else {
 34				rest = nil
 35			}
 36			if !lineMayCarryInvocation(line, hints) {
 37				continue
 38			}
 39			if scanLineInvocations(line, visit) {
 40				return true
 41			}
 42		}
 43		return false
 44	}
 45	
 46	// lineMayCarryInvocation applies the two prefilters: the caller's hints (nil
