     1	package claudecode
     2	
     3	import (
     4		"bytes"
     5		"encoding/json"
     6	
     7		"github.com/entireio/cli/cmd/entire/cli/agent"
     8		"github.com/entireio/cli/cmd/entire/cli/transcript"
     9	)
    10	
    11	// toolUseToken is the literal that must appear in a raw transcript line for it
    12	// to carry a tool_use content block. Both quotes are part of the token on
    13	// purpose: it makes the check exact without whitespace normalization, and it is
    14	// what keeps `"tool_use_id"` — which appears on every tool_result line, the
    15	// single largest false-positive class for any substring probe — from matching.
    16	var toolUseToken = []byte(`"tool_use"`)
    17	
    18	// ScanToolInvocations walks the Bash/Task-style tool calls recorded in a Claude
    19	// Code JSONL transcript. See agent.ToolInvocationScanner for the contract,
    20	// including that hints is a performance filter and not a semantic one.
    21	//
    22	// Lines are split by hand with bytes.IndexByte rather than with bufio.Scanner:
    23	// a single Claude Code transcript line routinely carries a multi-megabyte tool
    24	// result, so Scanner's 64KiB default token limit would silently truncate the
    25	// walk. Two byte-level prefilters run before any JSON work, so a transcript
    26	// with no candidate line costs one pass and zero allocations — the same order
    27	// as the substring probe this replaces, on the miss path that dominates.
    28	func (c *ClaudeCodeAgent) ScanToolInvocations(transcriptData []byte, hints [][]byte, visit func(agent.ToolInvocation) bool) bool {
    29		for rest := transcriptData; len(rest) > 0; {
    30			line := rest
    31			if idx := bytes.IndexByte(rest, '\n'); idx >= 0 {
    32				line, rest = rest[:idx], rest[idx+1:]
    33			} else {
    34				rest = nil
    35			}
    36			if !lineMayCarryInvocation(line, hints) {
    37				continue
    38			}
    39			if scanLineInvocations(line, visit) {
    40				return true
    41			}
    42		}
    43		return false
    44	}
    45	
    46	// lineMayCarryInvocation applies the two prefilters: the caller's hints (nil
    47	// means visit every line) and the tool_use token. Hints are checked first
    48	// because they are the selective half — a transcript typically has thousands of
    49	// tool_use lines and a handful mentioning whatever the caller is looking for.
    50	func lineMayCarryInvocation(line []byte, hints [][]byte) bool {
    51		if hints != nil && !containsAny(line, hints) {
    52			return false
    53		}
    54		return bytes.Contains(line, toolUseToken)
    55	}
    56	
    57	// containsAny reports whether line contains at least one of needles.
    58	func containsAny(line []byte, needles [][]byte) bool {
    59		for _, needle := range needles {
    60			if bytes.Contains(line, needle) {
    61				return true
    62			}
    63		}
    64		return false
    65	}
    66	
    67	// scanLineInvocations decodes one candidate line and offers each of its
    68	// tool_use blocks to visit. Malformed lines are skipped rather than reported:
    69	// the transcript is written by another process and may be mid-write, and this
    70	// is a telemetry read, never a correctness one.
    71	func scanLineInvocations(line []byte, visit func(agent.ToolInvocation) bool) bool {
    72		var parsed transcript.Line
    73		if err := json.Unmarshal(line, &parsed); err != nil || len(parsed.Message) == 0 {
    74			return false
    75		}
    76		// Only assistant envelopes carry live tool calls — the same gate every
    77		// other tool_use consumer in this package applies (ExtractModifiedFiles,
    78		// ExtractSkillEvents, ExtractAllModifiedFiles). Without it, a non-assistant
    79		// envelope whose message happens to decode into tool_use-shaped content
    80		// (replayed/sidechain or summary lines) would count as a real invocation.
    81		if parsed.Type != envelopeTypeAssistant {
    82			return false
    83		}
    84		var msg assistantMessage
    85		if err := json.Unmarshal(parsed.Message, &msg); err != nil {
    86			return false
    87		}
    88		for _, block := range msg.Content {
    89			if block.Type != transcript.ContentTypeToolUse || len(block.Input) == 0 {
    90				continue
    91			}
    92			var input toolInput
    93			if err := json.Unmarshal(block.Input, &input); err != nil {
    94				continue
    95			}
    96			if visit(agent.ToolInvocation{
    97				Tool:         block.Name,
    98				Command:      input.Command,
    99				SubagentType: input.SubagentType,
   100			}) {
   101				return true
   102			}
   103		}
   104		return false
   105	}

