328	// parsePushResult checks git push --porcelain output for ref status flags.
329	// In porcelain mode, each ref gets a tab-delimited status line:
330	//
331	//	<flag>\t<from>:<to>\t<summary>
332	//
333	// where flag '=' means the ref was already up-to-date. This is locale-independent,
334	// unlike the human-readable "Everything up-to-date" message.
335	func parsePushResult(output string) pushResult {
336		for _, line := range strings.Split(output, "\n") {
337			if strings.HasPrefix(line, "=\t") {
338				return pushResult{upToDate: true}
339			}
340		}
341		return pushResult{upToDate: false}
342	}
