358	// refSpec so existing remote-tracking works; non-branch refs use an explicit
359	// "refs/...:refs/..." refSpec with no tracking shadow. Neither forces: a
360	// non-fast-forward is rejected so doPushRef's fetch+rebase recovery runs (and a
361	// genuinely diverged ref is never silently overwritten — there is no
362	// server-side ref protection). This keeps one consistent non-force policy for
363	// every checkpoint ref, branch or per-checkpoint.
364	func tryPushRefCommon(ctx context.Context, remoteName string, ref plumbing.ReferenceName) (pushResult, error) {
365		refSpec := ref.Short()
366		if !ref.IsBranch() {
367			refSpec = ref.String() + ":" + ref.String()
368		}
369	
370		// Span the actual `git push` subprocess: on a slow remote (e.g. a custom
371		// git transport) this is typically where pre-push time is spent. Called once
372		// per push attempt, so a retry after fetch+rebase shows up as a second
373		// git_push step (git_push~1) in the trace. A rejected first push records an
374		// error flag, which signals the recovery path was taken.
375		_, pushSpan := perf.Start(ctx, "git_push")
376		result, err := remote.Push(ctx, remoteName, refSpec)
377		pushSpan.RecordError(err)
378		pushSpan.End()
379	
380		outputStr := result.Output

