const worktrees = [
  "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-settings-scope-leak",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-cursor-tool-scanner",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-attach-remote-hint",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-enable-import-cancellation",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/refactor-pi-session-cache"
];
const canonical = value => {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.keys(value).sort().map(k => [k, canonical(value[k])]));
  }
  return value;
};
for (const workdir of worktrees) {
  const [base, current] = await Promise.all([
    tools.exec_command({cmd:"git show HEAD:.entire/settings.json", workdir, yield_time_ms:10000, max_output_tokens:3000}),
    tools.exec_command({cmd:"sed -n '1,120p' .entire/settings.json", workdir, yield_time_ms:10000, max_output_tokens:3000})
  ]);
  let same = false;
  try {
    same = JSON.stringify(canonical(JSON.parse(base.output))) === JSON.stringify(canonical(JSON.parse(current.output)));
  } catch {}
  text(`${workdir}\tsemantic_settings_equal=${same}`);
}

